IReadOnlySet<string\> tags \= new HashSet<string\> { "dotnet", "csharp" };
string json \= JsonSerializer.Serialize(tags);
IReadOnlySet<string\> deserialized \= JsonSerializer.Deserialize<IReadOnlySet<string\>\>(json);

